<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Snake</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #10141c;
      --panel: #1a2230;
      --panel-light: #222d3e;
      --text: #eef5ff;
      --muted: #9aa9bd;
      --accent: #62e6a7;
      --accent-dark: #2da675;
      --food: #ff6b78;
      --grid: rgba(255, 255, 255, 0.045);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      background:
        radial-gradient(circle at top, #1b2637 0%, var(--bg) 55%),
        var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .game-shell {
      width: min(92vw, 570px);
      padding: 24px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 20px;
      background: rgba(26, 34, 48, 0.94);
      box-shadow: 0 24px 70px rgba(0, 0, 0, 0.4);
    }

    header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 18px;
    }

    h1 {
      margin: 0;
      font-size: 1.7rem;
      letter-spacing: 0.04em;
    }

    .score-box {
      min-width: 82px;
      padding: 7px 12px;
      border-radius: 10px;
      text-align: center;
      background: var(--panel-light);
      color: var(--muted);
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    #score {
      display: block;
      margin-top: 1px;
      color: var(--accent);
      font-size: 1.35rem;
      letter-spacing: normal;
    }

    .board-wrap {
      position: relative;
      width: 100%;
      aspect-ratio: 1;
      overflow: hidden;
      border: 3px solid #2d3b50;
      border-radius: 14px;
      background: #0c1119;
    }

    #snake {
      display: block;
      width: 100%;
      height: 100%;
    }

    .controls {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 9px;
      margin-top: 18px;
    }

    button {
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 9px;
      padding: 11px 8px;
      background: var(--panel-light);
      color: var(--text);
      cursor: pointer;
      font: inherit;
      font-weight: 700;
      transition: background 0.15s, transform 0.15s;
    }

    button:hover {
      background: #304057;
    }

    button:active {
      transform: translateY(1px);
    }

    #start {
      background: var(--accent-dark);
      border-color: var(--accent-dark);
    }

    #start:hover {
      background: #38bd86;
    }

    .hint {
      margin: 15px 0 0;
      color: var(--muted);
      font-size: 0.82rem;
      text-align: center;
    }

    @media (max-width: 480px) {
      .game-shell {
        padding: 16px;
      }
    }
  </style>
</head>
<body>
  <main class="game-shell">
    <header>
      <h1>Snake</h1>
      <div class="score-box">Score <span id="score">0</span></div>
    </header>

    <div class="board-wrap">
      <canvas id="snake" width="500" height="500" aria-label="Snake game board"></canvas>
    </div>

    <div class="controls">
      <button id="start" type="button">Start</button>
      <button id="pause" type="button">Pause</button>
      <button id="reset" type="button">Reset</button>
    </div>

    <p class="hint">Use the arrow keys to steer</p>
  </main>

  <script>
    (() => {
      const canvas = document.getElementById("snake");
      const ctx = canvas.getContext("2d");
      const scoreElement = document.getElementById("score");
      const startButton = document.getElementById("start");
      const pauseButton = document.getElementById("pause");
      const resetButton = document.getElementById("reset");

      const w = 20;
      const h = 20;
      const cell = canvas.width / w;
      const tickRate = 115;

      let body = [];
      let currentDirection = "right";
      let queuedDirection = "right";
      let currentFood = [14, 10];
      let currentScore = 0;
      let isAlive = true;
      let timer = null;

      const vectors = {
        up: [0, -1],
        down: [0, 1],
        left: [-1, 0],
        right: [1, 0]
      };

      function opposite(a, b) {
        return (
          (a === "up" && b === "down") ||
          (a === "down" && b === "up") ||
          (a === "left" && b === "right") ||
          (a === "right" && b === "left")
        );
      }

      function updateScore() {
        scoreElement.textContent = String(currentScore);
      }

      function randomFood() {
        const free = [];
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            if (!body.some(segment => segment[0] === x && segment[1] === y)) {
              free.push([x, y]);
            }
          }
        }
        if (free.length) {
          currentFood = free[Math.floor(Math.random() * free.length)];
        }
      }

      function roundedRect(x, y, width, height, radius) {
        const r = Math.min(radius, width / 2, height / 2);
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.arcTo(x + width, y, x + width, y + height, r);
        ctx.arcTo(x + width, y + height, x, y + height, r);
        ctx.arcTo(x, y + height, x, y, r);
        ctx.arcTo(x, y, x + width, y, r);
        ctx.closePath();
      }

      function draw() {
        ctx.fillStyle = "#0c1119";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.strokeStyle = "rgba(255,255,255,0.045)";
        ctx.lineWidth = 1;
        for (let x = 1; x < w; x++) {
          ctx.beginPath();
          ctx.moveTo(x * cell, 0);
          ctx.lineTo(x * cell, canvas.height);
          ctx.stroke();
        }
        for (let y = 1; y < h; y++) {
          ctx.beginPath();
          ctx.moveTo(0, y * cell);
          ctx.lineTo(canvas.width, y * cell);
          ctx.stroke();
        }

        if (currentFood) {
          const fx = currentFood[0] * cell + cell / 2;
          const fy = currentFood[1] * cell + cell / 2;
          ctx.fillStyle = "#ff6b78";
          ctx.shadowColor = "rgba(255,107,120,0.7)";
          ctx.shadowBlur = 12;
          ctx.beginPath();
          ctx.arc(fx, fy, cell * 0.29, 0, Math.PI * 2);
          ctx.fill();
          ctx.shadowBlur = 0;
        }

        body.forEach((segment, index) => {
          const pad = index === 0 ? 2.5 : 3.5;
          const x = segment[0] * cell + pad;
          const y = segment[1] * cell + pad;
          const size = cell - pad * 2;

          ctx.fillStyle = index === 0 ? "#8af2bf" : "#4bd494";
          roundedRect(x, y, size, size, 5);
          ctx.fill();

          if (index === 0) {
            ctx.fillStyle = "#10251d";
            const eyeSize = 2.2;
            const ex = currentDirection === "left" ? x + 5 :
              currentDirection === "right" ? x + size - 5 : x + size / 2;
            const ey = currentDirection === "up" ? y + 5 :
              currentDirection === "down" ? y + size - 5 : y + size / 2;
            ctx.beginPath();
            ctx.arc(ex, ey - (currentDirection === "left" || currentDirection === "right" ? 3 : 0), eyeSize, 0, Math.PI * 2);
            ctx.arc(ex, ey + (currentDirection === "left" || currentDirection === "right" ? 3 : 0), eyeSize, 0, Math.PI * 2);
            ctx.fill();
          }
        });

        if (!isAlive) {
          ctx.fillStyle = "rgba(5, 8, 13, 0.58)";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.fillStyle = "#ffffff";
          ctx.textAlign = "center";
          ctx.font = "700 28px system-ui, sans-serif";
          ctx.fillText("Game Over", canvas.width / 2, canvas.height / 2 - 4);
          ctx.font = "14px system-ui, sans-serif";
          ctx.fillStyle = "#b8c5d6";
          ctx.fillText("Press Reset to try again", canvas.width / 2, canvas.height / 2 + 25);
        }
      }

      function reset() {
        stopTimer();
        const cx = Math.floor(w / 2);
        const cy = Math.floor(h / 2);
        body = [[cx, cy], [cx - 1, cy], [cx - 2, cy]];
        currentDirection = "right";
        queuedDirection = "right";
        currentScore = 0;
        isAlive = true;
        randomFood();
        updateScore();
        draw();
      }

      function tick() {
        if (!isAlive) return;

        currentDirection = queuedDirection;
        const [dx, dy] = vectors[currentDirection];
        const head = body[0];
        const next = [head[0] + dx, head[1] + dy];
        const eating = currentFood &&
          next[0] === currentFood[0] &&
          next[1] === currentFood[1];

        if (next[0] < 0 || next[0] >= w || next[1] < 0 || next[1] >= h) {
          isAlive = false;
          stopTimer();
          draw();
          return;
        }

        const collisionBody = eating ? body : body.slice(0, -1);
        if (collisionBody.some(segment => segment[0] === next[0] && segment[1] === next[1])) {
          isAlive = false;
          stopTimer();
          draw();
          return;
        }

        body.unshift(next);

        if (eating) {
          currentScore++;
          randomFood();
          updateScore();
        } else {
          body.pop();
        }

        draw();
      }

      function setDir(direction) {
        if (!vectors[direction]) return;
        const basis = queuedDirection;
        if (opposite(direction, basis)) return;
        queuedDirection = direction;
      }

      function setFood(x, y) {
        x = Number(x);
        y = Number(y);
        if (Number.isInteger(x) && Number.isInteger(y) && x >= 0 && x < w && y >= 0 && y < h) {
          currentFood = [x, y];
          draw();
        }
      }

      function startTimer() {
        if (!isAlive || timer !== null) return;
        timer = setInterval(tick, tickRate);
      }

      function stopTimer() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
        }
      }

      startButton.addEventListener("click", startTimer);
      pauseButton.addEventListener("click", stopTimer);
      resetButton.addEventListener("click", reset);

      document.addEventListener("keydown", event => {
        const keys = {
          ArrowUp: "up",
          ArrowDown: "down",
          ArrowLeft: "left",
          ArrowRight: "right"
        };
        if (keys[event.key]) {
          event.preventDefault();
          setDir(keys[event.key]);
        }
      });

      window.game = {
        w,
        h,
        reset,
        tick,
        setDir,
        setFood,
        snake: () => body.map(segment => [segment[0], segment[1]]),
        food: () => currentFood ? [currentFood[0], currentFood[1]] : null,
        alive: () => isAlive,
        score: () => currentScore
      };

      reset();
    })();
  </script>
</body>
</html>
